class ConferenciaDeSomaFalhou(Exception):
    pass


def conferir_soma(lancamentos: Sequence[Lancamento], classificacoes: Sequence[Classificacao]) -> None:
    do_extrato = Counter(lancamento.chave_natural for lancamento in lancamentos)
    classificados = Counter(classificacao.lancamento.chave_natural for classificacao in classificacoes)
    soma_do_extrato = sum(lancamento.valor_centavos for lancamento in lancamentos)
    soma_por_destino = {
        destino: sum(c.lancamento.valor_centavos for c in classificacoes if c.destino is destino) for destino in Destino
    }
    soma_classificada = sum(soma_por_destino.values())
    if do_extrato == classificados and soma_do_extrato == soma_classificada:
        return
    sem_destino = (do_extrato - classificados).total()
    a_mais = (classificados - do_extrato).total()
    partes = " + ".join(f"{destino} {formatar_reais(soma)}" for destino, soma in soma_por_destino.items())
    raise ConferenciaDeSomaFalhou(
        f"Conferência de soma não fechou: os lançamentos do Extrato somam {formatar_reais(soma_do_extrato)}, "
        f"mas {partes} = {formatar_reais(soma_classificada)}; "
        f"{sem_destino} lançamento(s) sem destino e {a_mais} classificado(s) a mais. "
        "A execução parou sem gerar saídas."
    )
import re
import unicodedata
from datetime import date, datetime
from fractions import Fraction

_VALOR_PTBR = re.compile(r"\d{1,3}(\.\d{3})*,\d{2}")
_VALOR_COM_PONTO = re.compile(r"\d+\.\d{2}")
_DATA_PTBR = re.compile(r"\d{2}/\d{2}/\d{4}")
_DATA_ISO = re.compile(r"\d{4}-\d{2}-\d{2}")
_CNPJ_SEM_PONTUACAO = re.compile(r"\d{14}")
_CNPJ = r"\d{2}\.\d{3}\.\d{3}/\d{4}-\d{2}|\d{14}"
_CNPJ_INTEIRO = re.compile(_CNPJ)
_CNPJ_NO_TEXTO = re.compile(rf"(?<![\d./-])(?:{_CNPJ})(?![\d./-]*\d)")


class FormatoInvalido(ValueError):
    pass


def centavos_de_valor_ptbr(texto: str) -> int:
    if not _VALOR_PTBR.fullmatch(texto):
        raise FormatoInvalido(f"valor '{texto}' não está no formato 1.234,56")
    return int(texto.replace(".", "").replace(",", ""))


def centavos_de_valor_com_ponto(texto: str) -> int:
    if not _VALOR_COM_PONTO.fullmatch(texto):
        raise FormatoInvalido(f"valor '{texto}' não está no formato 1234.56")
    return int(texto.replace(".", ""))


def data_ptbr(texto: str) -> date:
    if not _DATA_PTBR.fullmatch(texto):
        raise FormatoInvalido(f"data '{texto}' não está no formato dd/mm/aaaa")
    return _data(texto, "%d/%m/%Y")


def data_iso(texto: str) -> date:
    if not _DATA_ISO.fullmatch(texto):
        raise FormatoInvalido(f"data '{texto}' não está no formato aaaa-mm-dd")
    return _data(texto, "%Y-%m-%d")


def _data(texto: str, formato: str) -> date:
    try:
        return datetime.strptime(texto, formato).date()
    except ValueError as erro:
        raise FormatoInvalido(f"data '{texto}' não existe") from erro


def formatar_reais(centavos: int) -> str:
    reais, resto = divmod(centavos, 100)
    return f"R$ {reais:,}".replace(",", ".") + f",{resto:02d}"


def formatar_percentual(percentual: Fraction, simbolo: bool = True) -> str:
    return f"{float(percentual):.1f}".replace(".", ",") + ("%" if simbolo else "")


def cnpj(texto: str) -> str:
    if not _CNPJ_INTEIRO.fullmatch(texto):
        raise FormatoInvalido(f"CNPJ '{texto}' não está no formato 00.000.000/0000-00 nem tem 14 dígitos")
    return _so_digitos(texto)


def cnpj_sem_pontuacao(texto: str) -> str:
    if not _CNPJ_SEM_PONTUACAO.fullmatch(texto):
        raise FormatoInvalido(f"CNPJ '{texto}' não tem 14 dígitos sem pontuação")
    return texto


def cnpjs_no_texto(texto: str) -> list[str]:
    return [_so_digitos(encontrado) for encontrado in _CNPJ_NO_TEXTO.findall(texto)]


def raiz_do_cnpj(cnpj: str) -> str:
    return cnpj[:8]


def _so_digitos(texto: str) -> str:
    return re.sub(r"\D", "", texto)


def nome_normalizado(texto: str) -> str:
    sem_acento = "".join(c for c in unicodedata.normalize("NFKD", texto) if not unicodedata.combining(c))
    return " ".join(re.sub(r"[^A-Z0-9]+", " ", sem_acento.upper()).split())
import json
import urllib.request
from collections.abc import Sequence
from typing import Protocol

from conciliacao.configuracao import ConfiguracaoDaIa
from conciliacao.dominio import Parecer, Resposta

VERSAO_DO_PROMPT = "nome-v1"

_INSTRUCOES = (
    "Você confere pagamentos recebidos por uma franqueadora. O extrato bancário mostra o nome do pagador cortado "
    "num limite de caracteres, às vezes abreviado, com palavras invertidas ou faltando, sem acento e sem pontuação.\n"
    "Decida se o nome do extrato é de uma empresa com algum dos nomes do franqueado informados.\n"
    "Primeiro compare palavra por palavra: cada palavra do extrato precisa ser igual a uma palavra do nome do "
    "franqueado ou ser o começo dela (abreviação). Palavras genéricas como LTDA, ME, EIRELI, CIA ou COMERCIO não "
    "identificam a empresa sozinhas.\n"
    "Responda pertence = true só quando as palavras que distinguem a empresa aparecem nos dois nomes. Se o extrato "
    "tem uma palavra distintiva que não existe no nome do franqueado, responda pertence = false.\n"
    "Na explicacao, diga em uma frase curta, em português, quais palavras correspondem ou quais não correspondem."
)

_FORMATO = {
    "type": "object",
    "properties": {"explicacao": {"type": "string"}, "pertence": {"type": "boolean"}},
    "required": ["explicacao", "pertence"],
}


class PareceristaDeNome(Protocol):
    def dar_parecer(self, nome_do_extrato: str, nomes_do_franqueado: Sequence[str]) -> Parecer: ...


class PareceristaOllama:
    def __init__(self, configuracao: ConfiguracaoDaIa) -> None:
        self._configuracao = configuracao

    def dar_parecer(self, nome_do_extrato: str, nomes_do_franqueado: Sequence[str]) -> Parecer:
        nomes = "\n".join(f"- {nome}" for nome in nomes_do_franqueado)
        pedido = {
            "model": self._configuracao.modelo,
            "stream": False,
            "format": _FORMATO,
            "options": {"temperature": 0},
            "messages": [
                {"role": "system", "content": _INSTRUCOES},
                {
                    "role": "user",
                    "content": f"Nome no extrato: {nome_do_extrato}\nNomes do franqueado:\n{nomes}\n"
                    "O nome do extrato é desse franqueado?",
                },
            ],
        }
        requisicao = urllib.request.Request(
            f"{self._configuracao.endereco.rstrip('/')}/api/chat",
            data=json.dumps(pedido).encode(),
            headers={"Content-Type": "application/json"},
        )
        try:
            with urllib.request.urlopen(requisicao, timeout=self._configuracao.tempo_limite_segundos) as resposta:
                conteudo = json.loads(json.load(resposta)["message"]["content"])
            pertence, explicacao = conteudo["pertence"], conteudo["explicacao"]
        except (OSError, ValueError, KeyError, TypeError) as erro:
            return self._parecer(Resposta.INDISPONIVEL, f"Ollama em {self._configuracao.endereco} não respondeu: {erro}")
        if not isinstance(pertence, bool) or not isinstance(explicacao, str):
            return self._parecer(Resposta.INDISPONIVEL, f"resposta fora do formato pedido: {conteudo}")
        return self._parecer(Resposta.SIM if pertence else Resposta.NAO, explicacao.strip())

    def _parecer(self, resposta: Resposta, explicacao: str) -> Parecer:
        return Parecer(resposta, explicacao, self._configuracao.modelo, VERSAO_DO_PROMPT)


class SemIaConfigurada:
    def dar_parecer(self, nome_do_extrato: str, nomes_do_franqueado: Sequence[str]) -> Parecer:
        return Parecer(Resposta.INDISPONIVEL, "falta a seção [ia] na configuração", "", VERSAO_DO_PROMPT)


def parecerista_da_configuracao(ia: ConfiguracaoDaIa | None) -> PareceristaDeNome:
    return PareceristaOllama(ia) if ia else SemIaConfigurada()

