@dataclass
class _Gerador:
    configuracao: ConfiguracaoDoGerador
    rng: random.Random = field(init=False)
    franqueados: list[_Franqueado] = field(default_factory=list)
    titulos: list[_Titulo] = field(default_factory=list)
