from conciliacao.configuracao import ConfiguracaoDaIa, carregar_configuracao
from conciliacao.dominio import Parecer, Resposta

MODELO_FALSO = "modelo-falso"
VERSAO_DO_PROMPT_FALSA = "prompt-falso-1"


class PareceristaFalso:
    def __init__(self, sim_para: Iterable[tuple[str, str]] = (), indisponivel: bool = False) -> None:
        self._sim_para = set(sim_para)
        self._indisponivel = indisponivel
        self.chamadas: list[tuple[str, tuple[str, ...]]] = []

    def dar_parecer(self, nome_do_extrato: str, nomes_do_franqueado: Sequence[str]) -> Parecer:
        self.chamadas.append((nome_do_extrato, tuple(nomes_do_franqueado)))
        if self._indisponivel:
            return self._parecer(Resposta.INDISPONIVEL, "Ollama fora do ar")
        for nome in nomes_do_franqueado:
            if (nome_do_extrato, nome) in self._sim_para:
                return self._parecer(Resposta.SIM, f"'{nome_do_extrato}' abrevia '{nome}'")
        return self._parecer(Resposta.NAO, f"'{nome_do_extrato}' não lembra nenhum nome do Franqueado")

    @staticmethod
    def _parecer(resposta: Resposta, explicacao: str) -> Parecer:
        return Parecer(resposta=resposta, explicacao=explicacao, modelo=MODELO_FALSO, versao_do_prompt=VERSAO_DO_PROMPT_FALSA)


def ollama_do_projeto() -> ConfiguracaoDaIa:
    ia = carregar_configuracao(Path(__file__).parent.parent / "conciliacao.toml").ia
    assert ia is not None
    try:
        with urllib.request.urlopen(f"{ia.endereco.rstrip('/')}/api/tags", timeout=2) as resposta:
            modelos = {modelo["name"] for modelo in json.load(resposta)["models"]}
    except OSError:
        pytest.skip(f"Ollama não está rodando em {ia.endereco}")
    if ia.modelo not in modelos:
        pytest.skip(f"modelo {ia.modelo} não está instalado no Ollama")
    return ia
from dataclasses import dataclass, field
from html.parser import HTMLParser

_VAZIOS = {"meta", "br", "hr", "img", "input", "link"}


@dataclass
class Elemento:
    tag: str
    atributos: dict[str, str]
    filhos: list["Elemento | str"] = field(default_factory=list)

    @property
    def texto(self) -> str:
        return " ".join(" ".join(parte.split()) for parte in self._textos() if parte.strip())

    @property
    def classes(self) -> set[str]:
        return set(self.atributos.get("class", "").split())

    def _textos(self) -> list[str]:
        textos: list[str] = []
        for filho in self.filhos:
            textos.extend([filho] if isinstance(filho, str) else filho._textos())
        return textos

    def todos(self, tag: str | None = None, classe: str | None = None) -> list["Elemento"]:
        encontrados: list[Elemento] = []
        for filho in self.filhos:
            if isinstance(filho, str):
                continue
            if (tag is None or filho.tag == tag) and (classe is None or classe in filho.classes):
                encontrados.append(filho)
            encontrados.extend(filho.todos(tag, classe))
        return encontrados

    def por_id(self, identificador: str) -> "Elemento":
        [elemento] = [e for e in self.todos() if e.atributos.get("id") == identificador]
        return elemento

    def tem_id(self, identificador: str) -> bool:
        return any(e.atributos.get("id") == identificador for e in self.todos())

    def linhas(self) -> list[list[str]]:
        return [[celula.texto for celula in linha.filhos if isinstance(celula, Elemento)] for linha in self.todos("tr")]


class _Construtor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.raiz = Elemento("documento", {})
        self._pilha = [self.raiz]

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        elemento = Elemento(tag, {nome: valor or "" for nome, valor in attrs})
        self._pilha[-1].filhos.append(elemento)
        if tag not in _VAZIOS:
            self._pilha.append(elemento)

    def handle_endtag(self, tag: str) -> None:
        if tag in _VAZIOS:
            return
        assert self._pilha[-1].tag == tag, f"</{tag}> fecha <{self._pilha[-1].tag}>"
        self._pilha.pop()

    def handle_data(self, data: str) -> None:
        self._pilha[-1].filhos.append(data)


def ler_pagina(html: str) -> Elemento:
    construtor = _Construtor()
    construtor.feed(html)
    construtor.close()
    assert construtor._pilha == [construtor.raiz], "elementos sem fechar"
    return construtor.raiz
